from skill import normalize_rows
r=[{'name':' x ','value':'2.5','count':'3','tag':'keep'}]
o=normalize_rows(r)
assert o==[{'name':'x','value':2.5,'count':3,'tag':'keep'}]
assert r[0]['value']=='2.5'
try: normalize_rows([{'value':'x','count':'1'}])
except ValueError: pass
else: raise AssertionError('invalid row accepted')
try: normalize_rows([{'value':'2','count':'-1'}])
except ValueError: pass
else: raise AssertionError('negative count accepted')

from skill import weighted_mean
assert weighted_mean([{'value':10,'count':8},{'value':30,'count':2}])==14
for rows in ([],[{'value':10,'count':0}],[{'value':2,'count':-1}]):
    try: weighted_mean(rows)
    except ValueError: pass
    else: raise AssertionError('invalid weights accepted')

from skill import summarize
r=[{'group':' a ','value':'10','count':'8'},{'group':'a','value':'30','count':'2'},{'group':'b','value':'5','count':'1'}]
assert summarize(r)=={'a':14,'b':5}
assert r[0]['group']==' a '
assert summarize([])=={}
